
from pathlib import Path
import pandas as pd
import matplotlib.pyplot as plt

# Project folders
PROJECT_DIR = Path(__file__).resolve().parent.parent
OUTPUT_DIR = PROJECT_DIR / "outputs"
CHART_DIR = OUTPUT_DIR / "charts"
CHART_DIR.mkdir(parents=True, exist_ok=True)


def read_spark_output(folder_name):
    """Read CSV part files generated by Spark."""
    folder = OUTPUT_DIR / folder_name
    files = list(folder.glob("part-*.csv"))

    if not files:
        raise FileNotFoundError(
            f"No Spark CSV files found in: {folder}"
        )

    return pd.concat(
        [pd.read_csv(file) for file in files],
        ignore_index=True
    )


def find_column(dataframe, candidates):
    """Find a column using possible column names."""
    for name in candidates:
        if name in dataframe.columns:
            return name

    raise ValueError(
        f"Could not find any of {candidates}. "
        f"Available columns: {list(dataframe.columns)}"
    )


def save_chart(filename):
    plt.tight_layout()
    plt.savefig(CHART_DIR / filename, dpi=300, bbox_inches="tight")
    plt.close()
    print("Created:", filename)


print("\n========== STEP 10: DATA VISUALIZATIONS ==========")

# Load Spark analytics
category_data = read_spark_output("sales_by_category")
monthly_data = read_spark_output("monthly_sales")
product_data = read_spark_output("product_performance")
funnel_data = read_spark_output("integrated_conversion")
customer_data = read_spark_output("customer_journey")

# -------------------------------------------------
# CHART 1: SALES OVERVIEW
# Category revenue and monthly revenue
# -------------------------------------------------

category_col = find_column(
    category_data, ["category_name", "category", "name"]
)
category_revenue = find_column(
    category_data, ["revenue", "total_revenue", "category_revenue"]
)

month_col = find_column(monthly_data, ["month"])
monthly_revenue = find_column(
    monthly_data, ["monthly_revenue", "revenue"]
)

category_plot = category_data.sort_values(
    category_revenue, ascending=True
)

monthly_data = monthly_data.sort_values(month_col)

fig, axes = plt.subplots(1, 2, figsize=(15, 6))

axes[0].barh(
    category_plot[category_col].astype(str),
    category_plot[category_revenue]
)
axes[0].set_title("Revenue by Product Category")
axes[0].set_xlabel("Revenue")
axes[0].set_ylabel("Category")

axes[1].plot(
    monthly_data[month_col].astype(str),
    monthly_data[monthly_revenue],
    marker="o"
)
axes[1].set_title("Monthly Sales Trend")
axes[1].set_xlabel("Month")
axes[1].set_ylabel("Revenue")
axes[1].tick_params(axis="x", rotation=45)

save_chart("01_sales_overview.png")


# -------------------------------------------------
# CHART 2: CUSTOMER SEGMENTATION
# -------------------------------------------------

value_col = find_column(
    customer_data, ["lifetime_value", "total_spent"]
)

customer_data[value_col] = pd.to_numeric(
    customer_data[value_col], errors="coerce"
).fillna(0)

def classify_customer(value):
    if value <= 0:
        return "No purchases"
    elif value <= 1000:
        return "Low value"
    elif value <= 2000:
        return "Medium value"
    else:
        return "High value"

customer_data["segment"] = customer_data[value_col].apply(
    classify_customer
)

segment_counts = (
    customer_data["segment"]
    .value_counts()
    .reindex(
        ["No purchases", "Low value", "Medium value", "High value"],
        fill_value=0
    )
)

plt.figure(figsize=(9, 6))
plt.bar(segment_counts.index, segment_counts.values)
plt.title("Customer Segmentation by Purchase Value")
plt.xlabel("Customer Segment")
plt.ylabel("Number of Customers")
plt.xticks(rotation=15)

save_chart("02_customer_segmentation.png")


# -------------------------------------------------
# CHART 3: TOP PRODUCT PERFORMANCE
# -------------------------------------------------

product_name = find_column(
    product_data, ["name", "product_name"]
)
product_revenue = find_column(
    product_data, ["revenue", "total_revenue"]
)

top_products = product_data.sort_values(
    product_revenue, ascending=False
).head(10).sort_values(product_revenue)

plt.figure(figsize=(12, 7))
plt.barh(
    top_products[product_name].astype(str),
    top_products[product_revenue]
)
plt.title("Top 10 Products by Revenue")
plt.xlabel("Revenue")
plt.ylabel("Product")

save_chart("03_product_performance.png")


# -------------------------------------------------
# CHART 4: SESSION CONVERSION FUNNEL
# -------------------------------------------------

status_col = find_column(
    funnel_data, ["conversion_status", "status"]
)
session_count = find_column(
    funnel_data, ["session_count", "count"]
)

funnel_data[session_count] = pd.to_numeric(
    funnel_data[session_count], errors="coerce"
).fillna(0)

funnel_plot = funnel_data.sort_values(
    session_count, ascending=False
)

plt.figure(figsize=(9, 6))
bars = plt.bar(
    funnel_plot[status_col].astype(str),
    funnel_plot[session_count]
)

for bar in bars:
    height = bar.get_height()
    plt.text(
        bar.get_x() + bar.get_width() / 2,
        height,
        str(int(height)),
        ha="center",
        va="bottom"
    )

plt.title("E-commerce Session Conversion Funnel")
plt.xlabel("Session Status")
plt.ylabel("Number of Sessions")

save_chart("04_conversion_funnel.png")


print("\n======================================")
print("ALL FOUR VISUALIZATIONS COMPLETED")
print("======================================")
print("Charts saved in:", CHART_DIR)
